import React from 'react';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import VehicleIcon from './VehicleIcon'; // Importez votre icône de véhicule personnalisée
import StationIcon from './StationIcon'; // Importez votre icône de station personnalisée

const MapComponent = ({ vehicles, stations, onMapClick }) => {
  return (
    <MapContainer center={[51.505, -0.09]} zoom={13} style={{ height: '100%', width: '100%' }}>
      <TileLayer
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        attribution="&copy; <a href='https://www.openstreetmap.org/copyright'>OpenStreetMap</a> contributors"
      />
      {vehicles.map((vehicle, index) => (
        <Marker key={index} position={[vehicle.lat, vehicle.lng]} icon={VehicleIcon}>
          <Popup>
            <div>
              <h3>{vehicle.name}</h3>
              <p>Capacity: {vehicle.battery_capacity}</p>
              <p>Battery: {vehicle.init_battery}</p>
              <p>Consumption: {vehicle.consumption}</p>
            </div>
          </Popup>
        </Marker>
      ))}
      {stations.map((station, index) => (
        <Marker key={index} position={[station.lat, station.lng]} icon={StationIcon}>
          <Popup>
            <div>
              <h3>{station.name}</h3>
              <p>Price per kwh: {station.price_per_kwh}</p>
              <p>Charging speed: {station.charging_speed}</p>
              <p>Buy price per kwh: {station.buy_price_per_kwh}</p>
              <p>Discharging speed: {station.discharging_speed}</p>
            </div>
          </Popup>
        </Marker>
      ))}
    </MapContainer>
  );
};

export default MapComponent;
